toolCalls.commandLine:
"C:\\Program Files\\PowerShell\\7\\pwsh.exe" -Command "@'
const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  page.on('console', msg => console.log('console', msg.type(), msg.text()));
  page.on('response', res => { if (res.url().includes('/api/')) console.log('api', res.status(), res.url()); });
  await page.goto('http://127.0.0.1:3007/');
  await page.getByRole('button', { name: 'GPT-4o' }).click();
  console.log('tiles', await page.locator('.tile').count());
  await page.locator('.tile').first().hover();
  await page.locator('.tile .add').first().click();
  await page.waitForTimeout(1000);
  console.log('toast', await page.getByRole('status').textContent());
  console.log('url', page.url());
  console.log('cart badge', await page.locator('.cbadge.show').first().textContent().catch(()=>'none'));
  await browser.close();
})();
'@ | node -"

